import {dwarfGuide,dwarfReferences,knownRunes,grudgeSlots} from './dwarf-guide.mjs';
import {derive} from './rules.mjs';
import {sourceLabel} from './sources.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function dwarfOriginPanel(R,s){if(!dwarfGuide(R)||s.species!=='Dwarf')return '';return `<section class="notice"><strong>Dwarf background · Dwarf Guide pp. 38–42</strong><p class="small muted">Names use the printed d1000 table. Surnames use a parent’s name plus sson or sdottir; you can edit either name freely. Clan and birthplace are background, with regional Skills/Talents chosen above.</p><div class="cols"><div class="field"><label for="dwarf-name-style">Forename column / surname ending</label><select id="dwarf-name-style" data-bind="dwarfNameStyle">${['Male','Female'].map(x=>`<option ${s.dwarfNameStyle===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="dwarf-parent-style">Parent-name column for surname rolls</label><select id="dwarf-parent-style" data-bind="dwarfParentStyle">${['Male','Female'].map(x=>`<option ${s.dwarfParentStyle===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label for="dwarf-birthplace">Birthplace</label><input id="dwarf-birthplace" data-bind="background" data-key="birthplace" value="${esc(s.background?.birthplace)}"></div><button data-action="dwarf-birthplace" type="button">Roll birthplace · d100</button><label class="check-row section-gap"><input type="checkbox" data-bind="longbeard" ${s.longbeard?'checked':''}>Optional Longbeard · p. 50</label>${s.longbeard?`<div class="field"><label for="longbeard-age">Longbeard age (120 or older)</label><input id="longbeard-age" type="number" min="120" step="1" data-bind="longbeardAge" value="${s.longbeardAge??''}"></div><p class="small purchase-error">${esc(R.dwarfCreation.longbeard.text)}</p>`:''}<p class="small muted">The appearance table referenced on p. 42 is missing from this PDF. Core appearance rolls are retained without its regional modifiers.</p></section>`;}
export function dwarfCareerPanel(R,s){if(!dwarfGuide(R)||s.species!=='Dwarf')return '';const peers=R.careers.filter(c=>c.id===s.career||c.alternativeFor===s.career||R.careers.find(x=>x.id===s.career)?.alternativeFor===c.id),updates=R.careerUpdates.filter(x=>x.careers.includes(s.career));return `<section class="notice"><label class="check-row"><input type="checkbox" data-bind="dwarfTrappingSwaps" ${s.dwarfTrappingSwaps?'checked':''}>Optional Dwarf equipment and weapon Skill swaps · p. 55</label><p class="small muted">Adds the printed alternatives to Career gear and matching weapon Skills. Choose the actual equipment in Gear and specialisations in Skills. Class equipment stays as printed. Unspecified ammunition quantities remain unresolved. Changing this option clears Career allocations and gear, and is locked after XP spending.</p></section>${peers.length>1?`<div class="field section-gap"><label for="dwarf-career-profile">Karak Ranger profile</label><select id="dwarf-career-profile" data-bind="dwarfCareerProfile">${peers.map(c=>`<option value="${esc(c.id)}" ${c.id===s.career?'selected':''}>${esc(sourceLabel(R,c))}</option>`).join('')}</select></div><p class="small muted">Each book’s profile remains intact. Archives I is the default when both are enabled.</p>`:''}${updates.length?`<section class="notice"><strong>Optional Dwarf Career levels · pp. 54–61</strong><p class="small muted">Choose each level separately. Switching clears Career allocations, gear and magic choices and is locked after XP spending.</p>${[2,3,4].map(level=>{const choices=updates.filter(x=>x.profile.level===level);return choices.length?`<div class="field"><label for="dwarf-level-${level}">Level ${level}</label><select id="dwarf-level-${level}" data-bind="dwarfCareerUpdate" data-key="${level}"><option value="">Standard Career level</option>${choices.map(x=>`<option value="${esc(x.id)}" ${s.dwarfCareerUpdates?.[level]===x.id?'selected':''} ${x.unavailable?'disabled':''}>${esc(x.name)} · p. ${x.page}${x.unavailable?' · unavailable':''}</option>`).join('')}</select></div>${choices.filter(x=>x.unavailable).map(x=>`<p class="small muted">${esc(x.name)}: ${esc(x.unavailable)}</p>`).join('')}`:'';}).join('')}</section>`:''}`;}
export function grudgePanel(R,s){const slots=grudgeSlots(s,derive(R,s).talents);if(!slots.length)return '';return `<h3>Ancestral Grudges · Dwarf Guide pp. 80–81</h3><p class="small muted">Choose a different culture or faction for each rank. Printed examples: Orcs, Goblins, Skaven, Trolls, Daemons of Khorne. Campaign XP awards are deferred.</p>${slots.map((_,i)=>`<div class="field"><label for="grudge-${i}">Grudge ${i+1}</label><input id="grudge-${i}" data-bind="grudgeTarget" data-key="${i}" value="${esc(s.grudgeTargets?.[i])}" maxlength="100"></div>`).join('')}`;}
export function runePanel(R,s){const runes=knownRunes(R,s,derive(R,s).talents);if(!runes.length)return '';return `<h3>Learned runes</h3><p class="small muted">These are runes you know how to craft, not enchanted items you own. Learning a Master Rune also grants the three Doom Runes. Crafting and live activation are deferred.</p>${runes.map(x=>`<details><summary>${esc(x.name)} · ${esc(x.form)} ${esc(sourceLabel(R,x))}</summary><p>${esc(x.text)}</p><p class="small muted">${esc(x.conversion)}</p></details>`).join('')}`;}
export function runeShopRows(names,row,section){const ordinary=[],groups=new Map();for(const name of names){const m=name.match(/^(Rune Magic|Master Rune Magic) \(([^:]+): /);if(!m){ordinary.push(name);continue;}const key=`${m[1]} · ${m[2]}`;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(name);}return ordinary.map(row).join('')+[...groups].map(([key,choices])=>choices.length===1?row(choices[0]):`<details class="talent-catalog-group" data-group="${esc(section+':'+key)}"><summary>${esc(key)} <span class="counter">${choices.length}</span></summary>${choices.map(row).join('')}</details>`).join('');}
export function runeChoiceDescription(R,name){const rune=R.runes.find(x=>name===`${x.master?'Master Rune Magic':'Rune Magic'} (${x.form}: ${x.name})`);return rune?`<p><strong>${esc(rune.name)} · ${esc(sourceLabel(R,rune))}</strong></p><p>${esc(rune.text)}</p><p class="small muted">${esc(rune.conversion)} Printed crafting SL: ${rune.sl} (reference only).</p>`:'';}
export function dwarfReview(R,s){return dwarfReferences(R,s).map(x=>`<p class="small muted">${esc(sourceLabel(R,x))}: ${esc(x.text)}</p>`).join('')+grudgePanel(R,s)+runePanel(R,s);}
